const crypto = require('crypto');

// Pega aquí el mismo token privado que ya usa tu nodo /whoami.
// No lo guardes en GitHub ni lo envíes al navegador.
const BOT_TOKEN = 'PEGA_AQUI_EL_TOKEN_REAL_DE_PUCELO_BOT';

function result(json) {
  return [{ json }];
}

function invalid(error) {
  return result({ ok: false, valid: false, error });
}

function parseQueryString(value) {
  const fields = {};

  try {
    for (const part of String(value).split('&')) {
      const separator = part.indexOf('=');
      if (separator < 0) continue;

      const key = decodeURIComponent(part.slice(0, separator).replace(/\+/g, ' '));
      const fieldValue = decodeURIComponent(part.slice(separator + 1).replace(/\+/g, ' '));
      fields[key] = fieldValue;
    }
  } catch {
    return null;
  }

  return fields;
}

if (!BOT_TOKEN || BOT_TOKEN.startsWith('PEGA_AQUI')) {
  throw new Error('Pega el token privado de Pucelo Bot en este nodo.');
}

const input = $input.first()?.json ?? {};
let body = input.body ?? input;

if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    return invalid('invalid_json');
  }
}

const initData = typeof body.initData === 'string' ? body.initData.trim() : '';
if (!initData) return invalid('telegram_init_data_missing');

const fields = parseQueryString(initData);
if (!fields) return invalid('telegram_init_data_malformed');

const receivedHash = fields.hash ?? '';
const authDate = Number(fields.auth_date);
if (!/^[a-f0-9]{64}$/i.test(receivedHash) || !Number.isInteger(authDate)) {
  return invalid('telegram_init_data_invalid');
}

const now = Math.floor(Date.now() / 1000);
if (authDate > now + 60 || now - authDate > 600) {
  return invalid('telegram_init_data_expired');
}

const dataCheckString = Object.keys(fields)
  .filter((key) => key !== 'hash')
  .sort()
  .map((key) => `${key}=${fields[key]}`)
  .join('\n');

const secretKey = crypto.createHmac('sha256', 'WebAppData').update(BOT_TOKEN).digest();
const expectedHash = crypto.createHmac('sha256', secretKey).update(dataCheckString).digest('hex');
const received = Buffer.from(receivedHash, 'hex');
const expected = Buffer.from(expectedHash, 'hex');

if (received.length !== expected.length || !crypto.timingSafeEqual(received, expected)) {
  return invalid('telegram_identity_invalid');
}

let user;
try {
  user = JSON.parse(fields.user ?? '{}');
} catch {
  return invalid('telegram_user_invalid');
}

if (!user || !Number.isSafeInteger(user.id)) {
  return invalid('telegram_user_invalid');
}

return result({
  ok: true,
  valid: true,
  telegram_id: String(user.id),
});

const auth = $('Validate Telegram initData').first()?.json ?? {};

if (auth.valid !== true) {
  return [{ json: auth }];
}

const items = $input.all()
  .map(({ json }) => json.fields ?? json)
  .filter((fields) => String(fields.owner_telegram_id ?? '') === String(auth.telegram_id))
  .map((fields) => ({
    id: fields['item-id'] ?? null,
    title: fields.title ?? '',
    description: fields.description ?? '',
    category: fields.category ?? 'Otros',
    zone: fields.zone ?? 'Valladolid',
    status: fields.status ?? 'hidden',
    created_at: fields.created_at ?? fields.CreatedAt ?? null,
    updated_at: fields.updated_at ?? fields.UpdatedAt ?? null,
    expires_at: fields.expires_at ?? null,
    completed_at: fields.completed_at ?? null,
    image_url: fields.image_url || null,
    owner_display_name: fields.owner_display_name ?? 'Vecindad',
    owner_username: fields.owner_username ?? fields.owner_telegram_username ?? fields.telegram_username ?? '',
    owner_telegram_id: String(fields.owner_telegram_id ?? ''),
    interest_count: Number(fields.interest_count ?? 0),
  }))
  .filter((item) => item.id && ['available', 'completed'].includes(item.status));

return [{
  json: {
    ok: true,
    items,
    total: items.length,
  },
}];
